export function evaluate({ inputs, time }) {
  const u = inputs.launchSpeed, g = inputs.gravity, m = inputs.mass;
  const T = 2 * u / g, ta = u / g;
  const t = sdk.clamp(time, 0, T);
  const y = u * t - g * t * t / 2;
  const v = u - g * t;
  const H = u * u / (2 * g);
  const eps = 0.005;
  let st = 'Rising';
  if (t <= 0) st = 'Ready to toss'; else if (t >= T - 1e-9) st = 'Back at launch height'; else if (Math.abs(t - ta) < 0.02) st = 'At the top'; else if (t > ta) st = 'Falling';
  const F = m * g;
  const o = [];
  o.push(...sdk.panel({ id: 'lane.motion', x: 10, y: 40, w: 300, h: 360, title: 'The motion', state: st }));
  o.push(...sdk.panel({ id: 'lane.graph', x: 330, y: 40, w: 300, h: 360, title: 'Velocity over time', state: '' }));
  o.push(sdk.axis('axis.h', { x: 60, y: 370, length: 290, orientation: 'y', min: 0, max: 2.2, ticks: [0, 1, 2], label: 'Height', unit: 'm' }));
  const py = h => 370 - h / 2.2 * 290 * 1;
  const by = 370 - y / 2.2 * 290;
  o.push(sdk.circle('ball.toss', 130, by, 24));
  o.push(...sdk.vector('vec.v', { x: 130, y: by }, { value: v, direction: 'up' }, { scale: 14, label: 'v' }));
  o.push(...sdk.vector('vec.a', { x: 160, y: by }, { value: -g, direction: 'up' }, { scale: 5, label: 'a', role: 'warning' }));
  o.push(...sdk.callout(190, 80, ['v = ' + sdk.format(v, 2) + ' m/s', 'a = ' + sdk.format(-g, 1) + ' m/s²', 'F = ' + sdk.format(F, 1) + ' N'], { id: 'callout.toss' }));
  const f = tt => [tt, u - g * tt];
  const pts = [];
  for (let i = 0; i <= 12; i++) { const tt = Math.min(t, T) * i / 12; pts.push({ x: tt, y: u - g * tt }); }
  if (pts.length < 2) pts.push({ x: 0, y: u });
  const full = [];
  for (let i = 0; i <= 12; i++) { const tt = 1.8 * i / 12; const vv = u - g * tt; full.push({ x: tt, y: sdk.clamp(vv, -5.5, 5.5) }); }
  o.push(...[sdk.plot('plot.vt', { x: 345, y: 80, w: 275, h: 270, axes: { x: { label: 'Time', min: 0, max: 1.8, unit: 's' }, y: { label: 'v', min: -5.5, max: 5.5, unit: 'm/s' } }, series: [{ label: 'v = u - g t', kind: 'line', points: full }, { label: 'so far', kind: 'line', points: pts }] })]);
  const motion = st;
  return { frame: { width: 640, height: 420, objects: o, readouts: [{ id: 'velocity', value: v }, { id: 'acceleration', value: -g }, { id: 'force', value: F }, { id: 'motionState', value: motion }] }, quantities: { launchSpeed: u, gravity: g, mass: m, apexTime: ta, apexHeight: H, height: y, velocity: v, acceleration: -g, force: F, motionState: 0 } };
}
